head.script:
// https://inswave01.atlassian.net/browse/WAEA-1220
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
};



// infoArray 항목에 담는 키만 다르고 나머지 옵션과 대상 그리드는 모든 버튼이 동일하다.
//  다운로드 성공 여부를 눈으로 확인할 수 있도록 성공 / 실패 콜백을 함께 등록해 결과창에 남긴다.
//  별도 정보 셀은 항상 Excel 의 F9 한 칸이며 데이터 영역(행 0~6 / 열 0~3)과 겹치지 않는다.
scwin.runCase = function (arrInfo, strFileName, strShow) {
    scwin.setReturnValue(strShow);

    target1.advancedExcelDownload({
        "fileName" : strFileName,
        "extension" : "xlsx",
        "sheetName" : "mysheet",
        "onSuccessCallback" : function () {
            scwin.setReturnValue("→ 다운로드 성공 : " + strFileName + ".xlsx");
            scwin.setReturnValue("");
        },
        "onFailureCallback" : function () {
            scwin.setReturnValue("→ 다운로드 실패 (파일 없음)");
            scwin.setReturnValue("");
        }
    }, arrInfo);
};



// [A] rowIndex / colIndex / rowSpan / colSpan 을 모두 설정한다. (정상 대조군)
scwin.btn_all_onclick = function () {
    scwin.runCase(
        [ { "rowIndex" : 8, "colIndex" : 5, "rowSpan" : 1, "colSpan" : 1, "text" : "별도 정보" } ],
        "info_all",
        "[A] rowIndex / colIndex / rowSpan / colSpan 4 개 모두 설정"
    );
};



// [B] rowSpan 만 생략한다.
scwin.btn_noRowSpan_onclick = function () {
    scwin.runCase(
        [ { "rowIndex" : 8, "colIndex" : 5, "colSpan" : 1, "text" : "별도 정보" } ],
        "info_no_rowspan",
        "[B] rowSpan 만 생략"
    );
};



// [C] colSpan 만 생략한다.
scwin.btn_noColSpan_onclick = function () {
    scwin.runCase(
        [ { "rowIndex" : 8, "colIndex" : 5, "rowSpan" : 1, "text" : "별도 정보" } ],
        "info_no_colspan",
        "[C] colSpan 만 생략"
    );
};



// [D] rowIndex 만 생략한다.
scwin.btn_noRowIndex_onclick = function () {
    scwin.runCase(
        [ { "colIndex" : 5, "rowSpan" : 1, "colSpan" : 1, "text" : "별도 정보" } ],
        "info_no_rowindex",
        "[D] rowIndex 만 생략"
    );
};



// [E] colIndex 만 생략한다.
scwin.btn_noColIndex_onclick = function () {
    scwin.runCase(
        [ { "rowIndex" : 8, "rowSpan" : 1, "colSpan" : 1, "text" : "별도 정보" } ],
        "info_no_colindex",
        "[E] colIndex 만 생략"
    );
};



// [F] 배열에 2 건을 담되 두 번째 항목만 rowSpan 을 생략한다.
scwin.btn_twoItems_onclick = function () {
    scwin.runCase(
        [
            { "rowIndex" : 8, "colIndex" : 5, "rowSpan" : 1, "colSpan" : 1, "text" : "별도 정보 1" },
            { "rowIndex" : 10, "colIndex" : 5, "colSpan" : 1, "text" : "별도 정보 2" }
        ],
        "info_two_items",
        "[F] 2 건 중 첫 번째는 4 개 모두 설정, 두 번째만 rowSpan 생략"
    );
};



// [G] rowSpan 에 0 을 넣는다. (값이 아니라 키 존재 여부가 조건임을 보이는 참고 대조)
scwin.btn_rowSpanZero_onclick = function () {
    scwin.runCase(
        [ { "rowIndex" : 8, "colIndex" : 5, "rowSpan" : 0, "colSpan" : 0, "text" : "별도 정보" } ],
        "info_span_zero",
        "[G] rowSpan / colSpan 에 0 설정 (참고)"
    );
};
